/** Native precious-metal processing, building states, tool tradeoff and frozen earlier placements. */
public final class PreciousSmoke {
 private record Metal(String name,Block ore,Block deep,Item raw,Item ingot,Block block,Block slab,Block stair,boolean diamond){}
 private static List<Metal> metals(){return List.of(new Metal("silver",PreciousContent.SILVER_ORE,PreciousContent.DEEPSLATE_SILVER_ORE,PreciousContent.RAW_SILVER,PreciousContent.SILVER_INGOT,PreciousContent.SILVER_BLOCK,PreciousContent.SILVER_SLAB,PreciousContent.SILVER_STAIRS,false),new Metal("platinum",PreciousContent.PLATINUM_ORE,PreciousContent.DEEPSLATE_PLATINUM_ORE,PreciousContent.RAW_PLATINUM,PreciousContent.PLATINUM_INGOT,PreciousContent.PLATINUM_BLOCK,PreciousContent.PLATINUM_SLAB,PreciousContent.PLATINUM_STAIRS,true));}
 public static void verify(ServerLevel l,Path d)throws Exception{recipes(l);dropsAndPick(l,d);buildings(l,d);legacy(l,d);natural(l,d);}
 private static void recipes(ServerLevel l){
  var manager=l.getServer().getRecipeManager();for(var m:metals()){
   for(var source:List.of(m.raw,m.ore.asItem(),m.deep.asItem())){var in=new SingleRecipeInput(new ItemStack(source));require(manager.getRecipeFor(RecipeType.SMELTING,in,l).orElseThrow().value().assemble(in).is(m.ingot),"native precious smelting");require(manager.getRecipeFor(RecipeType.BLASTING,in,l).orElseThrow().value().assemble(in).is(m.ingot),"native precious blasting");}
   String[][] shapes={{"BBB","BBB","BBB"},{"BBB"},{"B  ","BB ","BBB"}};int[] counts={1,6,4};var outputs=List.of(m.block,m.slab,m.stair);for(int k=0;k<3;k++){var grid=new ArrayList<ItemStack>();for(String row:shapes[k])for(char c:row.toCharArray())grid.add(c=='B'?new ItemStack(k==0?m.ingot:m.block.asItem()):ItemStack.EMPTY);var in=CraftingInput.of(3,shapes[k].length,grid);var out=manager.getRecipeFor(RecipeType.CRAFTING,in,l).orElseThrow().value().assemble(in);require(out.is(outputs.get(k).asItem())&&out.getCount()==counts[k],"native building recipe counts");}var unpack=CraftingInput.of(1,1,List.of(new ItemStack(m.block)));var out=manager.getRecipeFor(RecipeType.CRAFTING,unpack,l).orElseThrow().value().assemble(unpack);require(out.is(m.ingot)&&out.getCount()==9,"reversible precious storage");
  }
  var cells=List.of(new ItemStack(PreciousContent.SILVER_INGOT),new ItemStack(PreciousContent.SILVER_INGOT),new ItemStack(PreciousContent.SILVER_INGOT),ItemStack.EMPTY,new ItemStack(Items.STICK),ItemStack.EMPTY,ItemStack.EMPTY,new ItemStack(Items.STICK),ItemStack.EMPTY);var in=CraftingInput.of(3,3,cells);require(manager.getRecipeFor(RecipeType.CRAFTING,in,l).orElseThrow().value().assemble(in).is(PreciousContent.SILVER_PICKAXE),"native silver pick recipe");var bad=new ArrayList<>(cells);bad.set(1,ItemStack.EMPTY);require(manager.getRecipeFor(RecipeType.CRAFTING,CraftingInput.of(3,3,bad),l).isEmpty(),"pick cannot omit its head material");
 }
 private static void dropsAndPick(ServerLevel l,Path d)throws Exception{
  var pick=new ItemStack(PreciousContent.SILVER_PICKAXE);var iron=new ItemStack(Items.IRON_PICKAXE);var diamond=new ItemStack(Items.DIAMOND_PICKAXE);var steel=new ItemStack(SteelContent.STEEL_PICKAXE);var stone=Blocks.STONE.defaultBlockState();require(pick.getMaxDamage()==224&&pick.getMaxDamage()<iron.getMaxDamage()&&pick.getMaxDamage()<steel.getMaxDamage(),"silver shorter wear life");require(pick.getDestroySpeed(stone)>steel.getDestroySpeed(stone)&&pick.getDestroySpeed(stone)>iron.getDestroySpeed(stone)&&pick.getDestroySpeed(stone)<diamond.getDestroySpeed(stone),"silver speed tradeoff retains diamond advantage");require(pick.isCorrectToolForDrops(Blocks.DIAMOND_ORE.defaultBlockState())&&!pick.isCorrectToolForDrops(Blocks.OBSIDIAN.defaultBlockState())&&pick.is(net.minecraft.tags.ItemTags.PICKAXES),"iron-level harvest and native tool tag");require(pick.isValidRepairItem(new ItemStack(PreciousContent.SILVER_INGOT))&&!pick.isValidRepairItem(new ItemStack(PreciousContent.PLATINUM_INGOT))&&!pick.isValidRepairItem(new ItemStack(SteelContent.STEEL_INGOT)),"silver-only repair");
  var attribute=net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_DAMAGE;var slot=net.minecraft.world.entity.EquipmentSlot.MAINHAND;require(pick.get(net.minecraft.core.component.DataComponents.ATTRIBUTE_MODIFIERS).compute(attribute,1,slot)==iron.get(net.minecraft.core.component.DataComponents.ATTRIBUTE_MODIFIERS).compute(attribute,1,slot),"iron-level pick attack strength");
  var silk=diamond.copy();silk.enchant(l.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(net.minecraft.world.item.enchantment.Enchantments.SILK_TOUCH),1);
  for(var m:metals()){for(var ore:List.of(m.ore,m.deep)){require(diamond.isCorrectToolForDrops(ore.defaultBlockState())&&pick.isCorrectToolForDrops(ore.defaultBlockState())==!m.diamond&&!new ItemStack(Items.STONE_PICKAXE).isCorrectToolForDrops(ore.defaultBlockState()),"silver iron gate / platinum diamond gate");var drops=Block.getDrops(ore.defaultBlockState(),l,BlockPos.ZERO,null,null,diamond);require(drops.size()==1&&drops.getFirst().is(m.raw),"native raw drop");require(Block.getDrops(ore.defaultBlockState(),l,BlockPos.ZERO,null,null,silk).getFirst().is(ore.asItem()),"precious silk touch");}var drops=Block.getDrops(m.slab.defaultBlockState().setValue(SlabBlock.TYPE,SlabType.DOUBLE),l,BlockPos.ZERO,null,null,diamond);require(drops.size()==1&&drops.getFirst().is(m.slab.asItem())&&drops.getFirst().getCount()==2,"double slab drops two");for(var b:List.of(m.block,m.stair))require(Block.getDrops(b.defaultBlockState(),l,BlockPos.ZERO,null,null,diamond).getFirst().is(b.asItem()),"precious self drop");}
  var path=d.resolve("silver-pick.dat");var ops=RegistryOps.create(net.minecraft.nbt.NbtOps.INSTANCE,l.registryAccess());if(Files.exists(path)){var old=ItemStack.CODEC.parse(ops,net.minecraft.nbt.NbtIo.readCompressed(path,net.minecraft.nbt.NbtAccounter.unlimitedHeap())).getOrThrow();require(old.is(PreciousContent.SILVER_PICKAXE)&&old.getDamageValue()==37,"silver identity/damage persist");}pick.setDamageValue(37);net.minecraft.nbt.NbtIo.writeCompressed((net.minecraft.nbt.CompoundTag)ItemStack.CODEC.encodeStart(ops,pick).getOrThrow(),path);
 }
 private static void buildings(ServerLevel l,Path d)throws Exception{
  var player=new net.minecraft.world.entity.player.Player(l,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"PreciousBuilder")){@Override public net.minecraft.world.level.GameType gameMode(){return net.minecraft.world.level.GameType.CREATIVE;}};player.getInventory().setSelectedSlot(0);player.setYRot(90);var marker=d.resolve("precious-building-edits.txt");boolean prior=Files.exists(marker);int y=prior?Integer.parseInt(Files.readString(marker).trim()):l.getHeight(Heightmap.Types.WORLD_SURFACE,464,0)+4;
  for(int k=0;k<2;k++){var m=metals().get(k);int x=480+k*16,py=l.getHeight(Heightmap.Types.WORLD_SURFACE,x,0)+4;var a=new BlockPos(x,py,0);var b=a.east(2);var wet=a.east(4);for(var p:List.of(a,b,wet)){l.setBlock(p.below(),Blocks.STONE.defaultBlockState(),2);l.setBlock(p,Blocks.AIR.defaultBlockState(),2);}place(player,a.below(),m.slab);require(l.getBlockState(a).getValue(SlabBlock.TYPE)==SlabType.BOTTOM,"native lower slab");place(player,a,m.slab);require(l.getBlockState(a).getValue(SlabBlock.TYPE)==SlabType.DOUBLE,"slab combination");l.setBlock(b,Blocks.WATER.defaultBlockState(),2);place(player,b.below(),m.stair);require(l.getBlockState(b).is(m.stair)&&l.getBlockState(b).getValue(StairBlock.FACING)==Direction.WEST&&l.getBlockState(b).getValue(StairBlock.WATERLOGGED),"stair orientation/waterlogging");l.setBlock(wet,Blocks.WATER.defaultBlockState(),2);place(player,wet.below(),m.slab);require(l.getBlockState(wet).is(m.slab)&&l.getBlockState(wet).getValue(SlabBlock.WATERLOGGED),"slab waterlogging");
   var full=new BlockPos(464+k*4,y,0);var slab=full.east();var stair=full.east(2);if(!prior){l.setBlock(full,m.block.defaultBlockState(),2);l.setBlock(slab,m.slab.defaultBlockState().setValue(SlabBlock.TYPE,SlabType.DOUBLE),2);l.setBlock(stair,m.stair.defaultBlockState().setValue(StairBlock.FACING,Direction.WEST).setValue(StairBlock.WATERLOGGED,true),2);}require(l.getBlockState(full).is(m.block)&&l.getBlockState(slab).is(m.slab)&&l.getBlockState(slab).getValue(SlabBlock.TYPE)==SlabType.DOUBLE&&l.getBlockState(stair).is(m.stair)&&l.getBlockState(stair).getValue(StairBlock.FACING)==Direction.WEST&&l.getBlockState(stair).getValue(StairBlock.WATERLOGGED),"saved precious building states");
  }if(!prior){Files.writeString(marker,Integer.toString(y));l.getServer().saveEverything(false,true,true);}
 }
 private static void place(net.minecraft.world.entity.player.Player p,BlockPos support,Block b){var stack=new ItemStack(b);p.getInventory().setItem(0,stack);var hit=new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(support).add(0,.5,0),Direction.UP,support,false);stack.useOn(new net.minecraft.world.item.context.UseOnContext(p,net.minecraft.world.InteractionHand.MAIN_HAND,hit));}
 private static void legacy(ServerLevel l,Path d)throws Exception{
  long checked=0;int silver=0,platinum=0;java.util.function.Predicate<BlockState> p=s->s.is(PreciousContent.SILVER_ORE)||s.is(PreciousContent.PLATINUM_ORE);require(!new OreLayer(1,0,0,9,0,0).maybeHas(p)&&new OreLayer(1,0,0,10,0,0).maybeHas(p)&&new OreLayer(1,0,0,10,0,0).affectsPredicate(p),"new descriptor predicates version gated");
  try(var loader=MetallurgySmoke.historicalReader(Path.of(System.getProperty("blockbranch.oldFoolsCatalogClasses")).toUri().toURL())){var old=loader.loadClass("blockbranch.realistic.OreLayer");var ctor=old.getConstructor(long.class,int.class,int.class,int.class,int.class,int.class);var bind=old.getMethod("bind",int.class,int.class);var state=old.getMethod("state",int.class,int.class,int.class,int.class,BlockState.class,boolean.class);
   for(long seed:new long[]{424242,1,-17})for(int cx:new int[]{-1,0,1})for(boolean caves:new boolean[]{false,true}){var frozen=bind.invoke(ctor.newInstance(seed,cx,-1,9,65535,65535),64,64);var retained=new OreLayer(seed,cx,-1,9,65535,65535).bind(64,64);var current=new OreLayer(seed,cx,-1,10,65535,65535).bind(64,64);for(int z=0;z<16;z++)for(int x=0;x<16;x++)for(int depth=4;depth<=224;depth+=2){int y=64-depth;var host=(y<0?Blocks.DEEPSLATE:Blocks.STONE).defaultBlockState();var expected=(BlockState)state.invoke(frozen,x,y,z,64,host,caves);require(retained.state(x,y,z,64,host,caves)==expected,"published ore9 remains exact");var next=current.state(x,y,z,64,host,caves);if(expected!=host)require(next==expected,"precious fields cannot replace prior materials");else if(next!=host){if(isSilver(next)){silver++;require(depth>SilverVeins.MIN_DEPTH&&depth<SilverVeins.MAX_DEPTH,"silver band");}else{require(isPlatinum(next)&&depth>PlatinumVeins.MIN_DEPTH&&depth<PlatinumVeins.MAX_DEPTH,"only platinum in its band is added");platinum++;}}checked++;}}
   try{old.getMethod("decode",net.minecraft.nbt.CompoundTag.class).invoke(null,new OreLayer(1,0,0,10,0,0).encode());throw new AssertionError("old reader accepted10");}catch(java.lang.reflect.InvocationTargetException expected){require(expected.getCause() instanceof IllegalArgumentException,"prior fools reader rejects10");}
   var guard=loader.loadClass("blockbranch.cubic.ColumnWorldFormat").getMethod("check",Path.class,boolean.class,boolean.class,boolean.class);for(boolean decoration:new boolean[]{false,true}){var root=Files.createTempDirectory(d,"old-fools-guard-");ColumnWorldFormat.check(root,false,decoration,true);var marker=root.resolve("blockbranch-columns.txt");String before=Files.readString(marker);try{guard.invoke(null,root,true,decoration,true);throw new AssertionError("catalog10 reader accepted11");}catch(java.lang.reflect.InvocationTargetException expected){require(expected.getCause() instanceof IllegalStateException,"old fools reader rejects catalog11");}require(Files.readString(marker).equals(before),"old rejection preserves marker");}
  }
  require(silver>0&&platinum>0,"both precious fields have witnesses");Blockbranch.LOGGER.info("PRECIOUS frozenFoolsComparisons={} silver={} platinum={} oldReaderRejects10=true",checked,silver,platinum);
 }
 private static void natural(ServerLevel l,Path d)throws Exception{
  if(!(l.getChunkSource().getGenerator() instanceof RealisticGenerator g))return;if(g.oreDefinition()<10){require(g.oreDefinition()>=3&&g.oreDefinition()<=9,"retained prior definition");Blockbranch.LOGGER.info("PRECIOUS prior definition retained; no backfill");return;}require(g.oreDefinition()>=10,"precious-compatible definition");var origin=g.getOrigin(l.getChunkSource().randomState());
  for(var m:metals()){var marker=d.resolve(m.name+"-mined.txt");if(Files.exists(marker)){var v=Files.readString(marker).trim().split(",");var pos=new BlockPos(Integer.parseInt(v[0]),Integer.parseInt(v[1]),Integer.parseInt(v[2]));var value=((SparseColumn)l.getChunkAt(pos)).blockbranch$terrain().base().state(pos.getX(),pos.getY(),pos.getZ());require(l.getBlockState(pos).isAir()&&(m.diamond?isPlatinum(value):isSilver(value)),"natural precious edit survives reopen");continue;}
   boolean found=false;search:for(int dz=0;dz<4;dz++)for(int dx=0;dx<4;dx++){var chunk=l.getChunk(origin.x()+dx,origin.z()+dz);var base=((SparseColumn)chunk).blockbranch$terrain().base();require(base.ores().definition()==g.oreDefinition(),"native column descriptor10");var rt=TerrainProfile.decode(base.encode(l.palettedContainerFactory()),l.palettedContainerFactory());for(int z=0;z<16;z++)for(int x=0;x<16;x++)for(int depth=40;depth<=224;depth++){int y=base.groundHeight(x,z)-depth;var value=base.state(x,y,z);if(!(m.diamond?isPlatinum(value):isSilver(value)))continue;var pos=new BlockPos(chunk.getPos().getMinBlockX()+x,y,chunk.getPos().getMinBlockZ()+z);require(l.getBlockState(pos)==value&&rt.state(x,y,z)==value,"native precious witness agrees with snapshot");l.setBlock(pos,Blocks.AIR.defaultBlockState(),2);Files.writeString(marker,pos.getX()+","+pos.getY()+","+pos.getZ());l.getServer().saveEverything(false,true,true);Blockbranch.LOGGER.info("PRECIOUS natural {} witness={}",m.name,pos);found=true;break search;}}require(found,"no "+m.name+" in bounded sixteen-column search");
  }
 }
 private static boolean isSilver(BlockState s){return s.is(PreciousContent.SILVER_ORE)||s.is(PreciousContent.DEEPSLATE_SILVER_ORE);}
 private static boolean isPlatinum(BlockState s){return s.is(PreciousContent.PLATINUM_ORE)||s.is(PreciousContent.DEEPSLATE_PLATINUM_ORE);}
 private static void require(boolean v,String m){if(!v)throw new AssertionError(m);}
 private PreciousSmoke(){}
}
